#!/bin/sh
# Make build.nbt from scratch: build to a temp file, then move it into place (a failed build leaves the old one).
set -e
cd "$(dirname "$0")"
tmp="build.$$.tmp.nbt"
trap 'rm -f "$tmp"' EXIT
node build.mjs "$tmp"
mv "$tmp" build.nbt
echo "build.nbt ready"
----
// Lumber camp build: the ground, then every part in order; saves the structure to the path given as argv[2].
import { Grid, runParts } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { DATA_VERSIONS } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/structure.mjs";
import { SIZE, GROUND_Y, GRASS_BLOCK } from "./vocab/base.mjs";
import * as bunkhouse from "./parts/bunkhouse.mjs";
import * as sawmill from "./parts/sawmill.mjs";
import * as roofs from "./parts/roofs.mjs";
import * as fittings from "./parts/fittings.mjs";
import * as fire from "./parts/fire.mjs";
import * as grounds from "./parts/grounds.mjs";
import * as room1 from "./parts/room-1.mjs";
import * as room2 from "./parts/room-2.mjs";
import * as room3 from "./parts/room-3.mjs";
import * as room4 from "./parts/room-4.mjs";
import * as room5 from "./parts/room-5.mjs";
import * as room6 from "./parts/room-6.mjs";

const out = process.argv[2] ?? "build.nbt";
const g = new Grid(SIZE, { dataVersion: DATA_VERSIONS["26.3"] });

// The ground under everything (grounds.mjs adds the patches and paths over it; parts may replace it freely).
g.fill([0, GROUND_Y, 0], [SIZE[0] - 1, GROUND_Y, SIZE[2] - 1], GRASS_BLOCK);

// reroof reads the eave off the walls and throws on an empty shell, so the roof waits until the bunkhouse part has
// put something down: a probe run of the shell on its own grid (the stubs place nothing). A path that doesn't exist
// makes runParts skip the roof with a note.
const probe = new Grid(SIZE);
bunkhouse.build(probe);
const roof = probe.cells.size ? "roof.json" : "roof-after-shell.json";

runParts(g, [
  ["Bunkhouse log shell", bunkhouse.build],
  ["Sawmill pole frame", sawmill.build],
  ["Roofs", roofs.build],
  ["Fittings", fittings.build],
  ["Chimneys, stacks and fires", fire.build],
  ["Grounds, yard and woodshed", grounds.build],
  ["room: Bunkroom", room1.build],
  ["room: Mess and cook hall", room2.build],
  ["room: Loft", room3.build],
  ["room: Front porch", room4.build],
  ["room: Woodshed", room5.build],
  ["room: Sawmill hall", room6.build],
], { palette: "palette.json", roof });

g.save(out);
console.log(`saved ${out}: ${g.cells.size} blocks`);
----
// Part: Roofs. runParts lays the bunkhouse roof (roof.json) after the shell; this part lays the sawmill's granary roof
// (roof-sawmill.json, its monitor and gable planks), the porch shed roof and the woodshed shed roof by hand, and the
// woodshed's beam. Writes go through the runParts view, so a cell an earlier part owns is refused, not overwritten.
import { readFileSync } from "node:fs";
import { B, reroof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const SAWMILL_ROOF = JSON.parse(readFileSync(new URL("../roof-sawmill.json", import.meta.url), "utf8"));

export function build(g) {
  // Sawmill: the granary roof, keep box leaves the boiler stack's cells.
  const r = reroof(g, { ...SAWMILL_ROOF, keep: SAWMILL_ROOF.keep ?? [] });
  if (r.shift?.some(Boolean)) throw new Error(`sawmill roof moved the site by ${r.shift}`);

  // Porch shed roof, under the bunkhouse soffit (y=5 at z=6 and the eave course at z=7 are the roof's own): stairs
  // facing south on y=4 at z=5, resting on the posts and running face to face along the row; top slabs on y=4 at z=6
  // so the slope meets the soffit flush. The lantern chains at x=12 and 14 (y=4, z=6) stay air.
  for (let x = 5; x <= 17; x++) {
    g.set(x, 4, 5, ...B.stairs("spruce", "south", "bottom"));
    if (x !== 12 && x !== 14) g.set(x, 4, 6, ...B.slab("spruce", "top"));
  }

  // Woodshed shed roof, under the bunkhouse back soffit (the roof owns y=5 at z=18..19): top slabs on y=4 at z=19
  // (flush with the soffit), stairs facing north on y=4 at z=20 (the slope falls south), bottom slabs on y=4 at z=21 on
  // the posts. Beam (stripped spruce wood, axis x) at y=3: z=20 across x=5..12, and z=21 where the posts (x=5, 8, 12)
  // are not, so the P6 posts fall into air.
  for (let x = 5; x <= 12; x++) {
    g.set(x, 4, 19, ...B.slab("spruce", "top"));
    g.set(x, 4, 20, ...B.stairs("spruce", "north", "bottom"));
    g.set(x, 4, 21, ...B.slab("spruce", "bottom"));
    g.set(x, 3, 20, ...B.wood("stripped_spruce", "x"));
    if (![5, 8, 12].includes(x)) g.set(x, 3, 21, ...B.wood("stripped_spruce", "x"));
  }
}
